mapper.select:
SELECT  FROM training_session WHERE owner_id=#{owner}
AND status=#{status}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT id,owner_id,session_id,question_id,version_number,content_json,answer_condition AS `condition`,
  assistance_event_sequence,exposure_json,created_at FROM training_answer
WHERE owner_id=#{owner} AND session_id=#{sessionId} AND question_id=#{questionId} AND id=#{id}

SELECT id,version_number AS number,created_at,answer_condition AS `condition` FROM training_answer
WHERE owner_id=#{owner} AND session_id=#{sessionId} AND question_id=#{questionId}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

SELECT id,event_sequence AS `sequence`,event_kind AS kind,question_id,detail,duration_seconds,created_at
FROM training_event WHERE owner_id=#{owner} AND session_id=#{sessionId}
AND event_sequence < #{before}
ORDER BY event_sequence DESC LIMIT #{limit}

mapper.update:
UPDATE training_session SET question_count=question_count+1,revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected} AND question_count < 60
  AND revision < 9007199254740991 AND status='RUNNING'

UPDATE training_session SET observed_millis=#{observedMillis},unobserved_millis=#{unobservedMillis},
  paused_millis=#{pausedMillis},observation_at=#{observationAt},pause_started_at=#{pauseStartedAt}
WHERE owner_id=#{owner} AND id=#{id}

UPDATE training_question SET status='ANSWERED',latest_answer_id=#{answerId},answer_count=#{answerCount},
  draft_json=NULL,draft_saved_at=NULL,revision=revision+1
WHERE owner_id=#{owner} AND session_id=#{sessionId} AND id=#{id} AND revision=#{expected}
